#!/bin/bash
#
# Claude Code Status Bar - Generated by claudecode-status
# https://github.com/[[GITHUB_USER]]/claudecode-status
#

# ==================== CONFIGURATION ====================
# Theme: gray, orange, blue, teal, green, lavender, rose, gold, slate, cyan
COLOR="[[COLOR]]"

# Enabled modules (set by installer)
SHOW_GIT=[[SHOW_GIT]]
SHOW_PROJECT_TYPE=[[SHOW_PROJECT_TYPE]]
SHOW_CLAUDE_MD=[[SHOW_CLAUDE_MD]]
SHOW_TIME=[[SHOW_TIME]]
SHOW_SYSTEM=[[SHOW_SYSTEM]]
SHOW_CLOUD=[[SHOW_CLOUD]]

# ==================== COLOR SETUP ====================
C_RESET='\033[0m'
C_GRAY='\033[38;5;245m'
C_BAR_EMPTY='\033[38;5;238m'
C_BAR_FULL='\033[38;5;74m'

case "$COLOR" in
  orange)   C_ACCENT='\033[38;5;173m' ;;
  blue)     C_ACCENT='\033[38;5;74m' ;;
  teal)     C_ACCENT='\033[38;5;66m' ;;
  green)    C_ACCENT='\033[38;5;71m' ;;
  lavender) C_ACCENT='\033[38;5;139m' ;;
  rose)     C_ACCENT='\033[38;5;132m' ;;
  gold)     C_ACCENT='\033[38;5;136m' ;;
  slate)    C_ACCENT='\033[38;5;60m' ;;
  cyan)     C_ACCENT='\033[38;5;37m' ;;
  *)        C_ACCENT="$C_GRAY" ;;
esac

# ==================== PARSE INPUT ====================
input=$(cat)
model=$(echo "$input" | jq -r '.model.display_name // .model.id // "?"')
cwd=$(echo "$input" | jq -r '.cwd // empty')
dir=$(basename "$cwd" 2>/dev/null || echo "?")

# ==================== HELPER FUNCTIONS ====================

# Detect project type
get_project_type() {
    local project_dir="$1"
    local project_type=""

    if [[ -f "$project_dir/package.json" ]]; then
        project_type="📦 Node"
    elif [[ -f "$project_dir/requirements.txt" ]] || [[ -f "$project_dir/pyproject.toml" ]] || [[ -f "$project_dir/setup.py" ]]; then
        project_type="🐍 Python"
    elif [[ -f "$project_dir/Cargo.toml" ]]; then
        project_type="🦀 Rust"
    elif [[ -f "$project_dir/go.mod" ]]; then
        project_type="🔵 Go"
    elif [[ -f "$project_dir/pom.xml" ]] || [[ -f "$project_dir/build.gradle" ]]; then
        project_type="☕ Java"
    elif [[ -f "$project_dir/Gemfile" ]]; then
        project_type="💎 Ruby"
    elif [[ -f "$project_dir/composer.json" ]]; then
        project_type="🐘 PHP"
    elif [[ -d "$project_dir/.git" ]]; then
        project_type="📁 Git"
    else
        project_type="📁 Dir"
    fi

    echo "$project_type"
}

# Get Git info
get_git_info() {
    local repo_dir="$1"
    local git_info=""

    if [[ -d "$repo_dir/.git" ]]; then
        local branch=$(git -C "$repo_dir" branch --show-current 2>/dev/null)
        if [[ -n "$branch" ]]; then
            local file_count=$(git -C "$repo_dir" --no-optional-locks status --porcelain -uall 2>/dev/null | wc -l | tr -d ' ')
            local status_icon="✅"
            [[ "$file_count" -gt 0 ]] && status_icon="📝$file_count"

            # Check sync status
            local upstream=$(git -C "$repo_dir" rev-parse --abbrev-ref @{upstream} 2>/dev/null)
            if [[ -n "$upstream" ]]; then
                local counts=$(git -C "$repo_dir" rev-list --left-right --count HEAD...@{upstream} 2>/dev/null)
                local ahead=$(echo "$counts" | cut -f1)
                local behind=$(echo "$counts" | cut -f2)
                if [[ "$ahead" -gt 0 ]]; then
                    status_icon="⬆️$ahead"
                elif [[ "$behind" -gt 0 ]]; then
                    status_icon="⬇️$behind"
                fi
            fi

            git_info=" | 🔀${branch} ${status_icon}"
        fi
    fi

    echo "$git_info"
}

# Get CLAUDE.md indicator
get_claude_md_indicator() {
    local check_dir="$1"
    while [[ "$check_dir" != "/" ]]; do
        if [[ -f "$check_dir/CLAUDE.md" ]]; then
            echo " | 📋CLAUDE"
            return
        fi
        check_dir=$(dirname "$check_dir")
    done
    echo ""
}

# Get time info
get_time_info() {
    local time_str=$(date '+%H:%M')
    echo " | 🕐${time_str}"
}

# Get system resource info
get_system_info() {
    # Get memory usage percentage (Linux)
    local mem_info=$(free | grep Mem | awk '{printf "%.0f", $3/$2 * 100}')
    echo " | 💾${mem_info}%"
}

# Get cloud environment info
get_cloud_info() {
    # Check if running on Alibaba Cloud
    if [[ -f /etc/aliyun-release ]] || [[ -n "$ALICLOUD_REGION" ]]; then
        echo " | ☁️阿里云"
    elif curl -s --connect-timeout 1 http://100.100.100.200/latest/meta-data/region-id 2>/dev/null | grep -q "cn-"; then
        echo " | ☁️阿里云"
    else
        echo ""
    fi
}

# Build token usage bar
get_token_bar() {
    local transcript_path="$1"
    local max_context="$2"
    local max_k=$((max_context / 1000))
    local bar_width=10
    local baseline=20000

    local context_length=0
    if [[ -n "$transcript_path" && -f "$transcript_path" ]]; then
        context_length=$(jq -s '
            map(select(.message.usage and .isSidechain != true and .isApiErrorMessage != true)) |
            last |
            if . then
                (.message.usage.input_tokens // 0) +
                (.message.usage.cache_read_input_tokens // 0) +
                (.message.usage.cache_creation_input_tokens // 0)
            else 0 end
        ' < "$transcript_path" 2>/dev/null)
    fi

    local pct
    if [[ "$context_length" -gt 0 ]]; then
        pct=$((context_length * 100 / max_context))
    else
        pct=$((baseline * 100 / max_context))
    fi
    [[ $pct -gt 100 ]] && pct=100

    local bar=""
    for ((i=0; i<bar_width; i++)); do
        local bar_start=$((i * 10))
        local progress=$((pct - bar_start))
        if [[ $progress -ge 8 ]]; then
            bar+="${C_ACCENT}█${C_RESET}"
        elif [[ $progress -ge 3 ]]; then
            bar+="${C_ACCENT}▄${C_RESET}"
        else
            bar+="${C_BAR_EMPTY}░${C_RESET}"
        fi
    done

    echo "${bar} ${C_GRAY}${pct}% of ${max_k}k${C_RESET}"
}

# ==================== BUILD OUTPUT ====================

# Start with model
output="${C_ACCENT}${model}${C_GRAY}"

# Project type (if enabled)
if [[ "$SHOW_PROJECT_TYPE" == "true" ]]; then
    project_type=$(get_project_type "$cwd")
    output+=" | ${project_type}"
fi

# Current directory
output+=" | 📁${dir}"

# Git info (if enabled)
if [[ "$SHOW_GIT" == "true" ]]; then
    output+=$(get_git_info "$cwd")
fi

# CLAUDE.md indicator (if enabled)
if [[ "$SHOW_CLAUDE_MD" == "true" ]]; then
    output+=$(get_claude_md_indicator "$cwd")
fi

# Time info (if enabled)
if [[ "$SHOW_TIME" == "true" ]]; then
    output+=$(get_time_info)
fi

# System resources (if enabled)
if [[ "$SHOW_SYSTEM" == "true" ]]; then
    output+=$(get_system_info)
fi

# Cloud environment (if enabled)
if [[ "$SHOW_CLOUD" == "true" ]]; then
    output+=$(get_cloud_info)
fi

# Token usage bar (always shown)
transcript_path=$(echo "$input" | jq -r '.transcript_path // empty')
max_context=$(echo "$input" | jq -r '.context_window.context_window_size // 200000')
token_bar=$(get_token_bar "$transcript_path" "$max_context")
output+=" | ${token_bar}"

printf '%b\n' "$output"
